LABELS = ("positive", "negative", "neutral")


class Harness:
    def run(self, task, model, trace):
        prompt = ("Classify the sentiment of the review as exactly one of: "
                  + ", ".join(LABELS) + ". Review: " + task["input"])
        reply = model(prompt).strip().lower()
        for label in LABELS:
            if label in reply:
                return {"output": label}
        return {"output": "neutral"}

